CREATE OR REPLACE FUNCTION public.biz_period_department_any(_user uuid,_kind text,_y integer,_p integer) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.department_id FROM public.biz_department_members m WHERE m.user_id=_user AND m.started_at < ((public.biz_period_end_date(_kind,_y,_p)+1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh') AND (m.ended_at IS NULL OR m.ended_at>(public.biz_period_start_date(_kind,_y,_p)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')) AND (m.ended_at IS NULL OR m.ended_at>m.started_at) ORDER BY m.started_at DESC,m.id DESC LIMIT 1 $$;
CREATE FUNCTION private.biz_report_obligations(_year integer,_pk text,_period integer) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 WITH days AS (SELECT day_::date day_ FROM generate_series(public.biz_period_start_date(_pk,_year,_period)::timestamp,public.biz_period_end_date(_pk,_year,_period)::timestamp,interval '1 day') day_), candidates AS (SELECT DISTINCT k.pk,CASE WHEN k.pk='week' THEN to_char(day_,'IYYY')::integer ELSE extract(year FROM day_)::integer END y,CASE k.pk WHEN 'day' THEN (day_-make_date(extract(year FROM day_)::integer,1,1))+1 WHEN 'week' THEN to_char(day_,'IW')::integer WHEN 'month' THEN extract(month FROM day_)::integer ELSE extract(quarter FROM day_)::integer END p FROM days CROSS JOIN (VALUES('day'),('week'),('month'),('quarter')) k(pk)), members AS (SELECT pr.id user_id,pr.full_name employee_name,c.*,public.biz_period_department_any(pr.id,c.pk,c.y,c.p) department_id,public.biz_period_start_date(c.pk,c.y,c.p) starts FROM public.profiles pr CROSS JOIN candidates c), obligations AS (SELECT m.*,d.id document_id,d.first_submitted_at,CASE WHEN d.deadline_frozen THEN d.deadline ELSE public.biz_any_deadline_at('report_'||m.pk,m.y,m.p) END deadline,d.official_version_id,coalesce((SELECT status FROM public.biz_document_versions WHERE document_id=d.id ORDER BY version DESC LIMIT 1),'missing') approval_status FROM members m LEFT JOIN public.biz_documents d ON d.user_id=m.user_id AND d.kind='report' AND d.period_kind=m.pk AND d.year=m.y AND d.period=m.p WHERE m.department_id IS NOT NULL AND (d.id IS NOT NULL OR (public.biz_report_cycle_of(m.user_id,m.starts)=m.pk AND (m.pk<>'day' OR coalesce(public.biz_report_cycle_config_of(m.user_id,m.starts)->'workdays'->>(extract(isodow FROM m.starts)::integer::text),'true')<>'false')))) SELECT coalesce(jsonb_agg(jsonb_build_object('user_id',user_id,'employee_name',employee_name,'department_id',department_id,'kind','report','period_kind',pk,'year',y,'period',p,'period_start',starts,'period_end',public.biz_period_end_date(pk,y,p),'first_submitted_at',first_submitted_at,'time_status',CASE WHEN document_id IS NULL AND public.biz_any_phase('report',pk,y,p,now()) IN ('none','not_open') THEN 'upcoming' ELSE public.biz_deadline_status(deadline,first_submitted_at,now()) END,'approval_status',approval_status,'official',official_version_id IS NOT NULL)),'[]') FROM obligations $$;
REVOKE ALL ON FUNCTION private.biz_report_obligations(integer,text,integer) FROM PUBLIC,anon,authenticated,service_role;
DO $patch$
DECLARE f text;sig text;start_ integer;end_ integer;replacement text;
BEGIN
 FOREACH sig IN ARRAY ARRAY['public.biz_dashboard_read(integer,text,integer,uuid,uuid,text)','private.biz_dashboard_global_read(integer,text,integer,uuid,uuid,text)'] LOOP
 SELECT pg_get_functiondef(sig::regprocedure) INTO f;start_:=position('), obligations AS (' IN f);end_:=position('), scoped_obligations AS (' IN f);IF start_=0 OR end_<=start_ THEN RAISE EXCEPTION 'Obligation shape changed %',sig;END IF;
 replacement:=$cte$), obligations AS (
 SELECT p.id user_id,p.full_name employee_name,'plan'::text kind,coalesce(d.department_id,public.biz_period_department(p.id,_year,_period_kind,_period)) department_id,d.first_submitted_at,public.biz_deadline_status(CASE WHEN d.deadline_frozen THEN d.deadline ELSE public.biz_deadline_at('plan_'||_period_kind,_year,_period) END,d.first_submitted_at,now()) time_status,coalesce((SELECT status FROM public.biz_document_versions WHERE document_id=d.id ORDER BY version DESC LIMIT 1),'missing') approval_status,d.official_version_id IS NOT NULL official FROM public.profiles p LEFT JOIN public.biz_documents d ON d.user_id=p.id AND d.kind='plan' AND d.period_kind=_period_kind AND d.year=_year AND d.period=_period WHERE _period_kind IN ('month','quarter','year') AND public.biz_period_department(p.id,_year,_period_kind,_period) IS NOT NULL AND (_user_id IS NULL OR p.id=_user_id)
 UNION ALL SELECT user_id,employee_name,'report',department_id,first_submitted_at,time_status,approval_status,official FROM jsonb_to_recordset(private.biz_report_obligations(_year,_period_kind,_period)) o(user_id uuid,employee_name text,department_id uuid,first_submitted_at timestamptz,time_status text,approval_status text,official boolean) WHERE _user_id IS NULL OR user_id=_user_id
 $cte$;f:=substring(f from 1 for start_-1)||replacement||substring(f from end_);EXECUTE f;END LOOP;
 SELECT pg_get_functiondef('private.biz_published_facts(integer)'::regprocedure) INTO f;f:=replace(f,'''actual'',CASE WHEN official_version_id IS NOT NULL THEN f->>''actual'' END','''actual'',f->>''actual''');EXECUTE f;
 -- ISO workday map keys are strings, never numeric JSON operators, on every shared day-cycle path.
 FOREACH sig IN ARRAY ARRAY['private.biz_report_actual_range(uuid,uuid,date,date,text)','public.biz_my_work(text)','public.biz_document_start(text,text,integer,integer,text)'] LOOP SELECT pg_get_functiondef(sig::regprocedure) INTO f;f:=replace(f,'->>extract(isodow FROM day_)','->>(extract(isodow FROM day_)::integer::text)');f:=replace(f,'->>extract(isodow FROM dd)','->>(extract(isodow FROM dd)::integer::text)');f:=replace(f,'->>extract(isodow FROM pstart)','->>(extract(isodow FROM pstart)::integer::text)');EXECUTE f;END LOOP;
END $patch$;